import{_ as a,c as t,o,al as i,j as s}from"./chunks/framework.CT7RwC5a.js";const u=JSON.parse('{"title":"Debugging with GDB","description":"","frontmatter":{},"headers":[],"relativePath":"ko/debug/gdb_debugging.md","filePath":"ko/debug/gdb_debugging.md"}'),r={name:"ko/debug/gdb_debugging.md"};function n(l,e,d,h,g,p){return o(),t("div",null,e[0]||(e[0]=[i('<h1 id="debugging-with-gdb" tabindex="-1">Debugging with GDB <a class="header-anchor" href="#debugging-with-gdb" aria-label="Permalink to &quot;Debugging with GDB&quot;">​</a></h1><p>The <a href="https://sourceware.org/gdb/documentation/" target="_blank" rel="noreferrer">GNU DeBugger (GDB)</a> comes installed with the compiler toolchain in the form of the <code>arm-none-eabi-gdb</code> binary. The debugger reads the debug symbols inside an ELF file to understand the static and dynamic memory layout of the PX4 firmware. To access the PX4 autopilot microcontroller, it needs to connect to a <a href="https://sourceware.org/gdb/current/onlinedocs/gdb.html/Connecting.html" target="_blank" rel="noreferrer">Remote Target</a>, which is provided by a <a href="./swd_debug.html">SWD debug probe</a>.</p><p>The flow of information looks like this:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Developer</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> GDB</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> GDB</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Server</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Debug</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Probe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SWD</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PX4</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Autopilot.</span></span></code></pre></div><h2 id="quickstart" tabindex="-1">Quickstart <a class="header-anchor" href="#quickstart" aria-label="Permalink to &quot;Quickstart&quot;">​</a></h2><p>To start a debugging session you typically:</p><ol><li>Need a specialized <a href="./../debug/swd_debug.html#debug-probes">SWD debug probe</a>.</li><li>Find and connect to the <a href="./../debug/swd_debug.html#autopilot-debug-ports">SWD debug port</a>. You may need a <a href="./swd_debug.html#debug-adapters">debug adapter</a>.</li><li>Configure and start the debug probe to create a GDB server.</li><li>Launch GDB and connect to the GDB server as a remote target.</li><li>Debug your firmware interactively.</li></ol><p>See the debug probe documentation for details on how to setup your debug connection:</p><ul><li><a href="./probe_jlink.html">SEGGER J-Link</a>: commercial probe, no built-in serial console, requires adapter.</li><li><a href="./probe_bmp.html">Black Magic Probe</a>: integrated GDB server and serial console, requires adapter.</li><li><a href="./probe_stlink.html">STLink</a>: best value, integrated serial console, adapter must be soldered.</li></ul><p>We recommend using the J-Link with the Pixhawk Debug Adapter or the STLinkv3-MINIE with a soldered custom cable.</p><p>연결되면, 다음과 같은 일반적인 GDB 명령을 사용할 수 있습니다.</p><ul><li><code>continue</code> to continue program execution</li><li><code>run</code> to start from the beginning</li><li><code>backtrace</code> to see the backtrace</li><li><code>break somewhere.cpp:123</code> to set a breakpoint</li><li><code>delete somewhere.cpp:123</code> to remove it again</li><li><code>info locals</code> to print local variables</li><li><code>info registers</code> to print the registers</li></ul><p>Consult the <a href="https://sourceware.org/gdb/documentation/" target="_blank" rel="noreferrer">GDB documentation</a> for more details.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>To avoid having to type all commands to connect in GDB each time, you can write them into <code>~/.gdbinit</code>.</p></div><h2 id="다음-단계" tabindex="-1">다음 단계 <a class="header-anchor" href="#다음-단계" aria-label="Permalink to &quot;다음 단계&quot;">​</a></h2><p>You&#39;ve now connected the flight controller to an SWD debug probe!</p><p>The following topics explain how to start on-target debugging:</p><ul><li><a href="./eclipse_jlink.html">MCU Eclipse/J-Link Debugging for PX4</a>.</li><li><a href="./../dev_setup/vscode.html">Visual Studio Code IDE (VSCode)</a>.</li></ul><h2 id="비디오" tabindex="-1">비디오 <a class="header-anchor" href="#비디오" aria-label="Permalink to &quot;비디오&quot;">​</a></h2><p>The following video provides an overview of the tooling available for advanced debugging of PX4 via GDB. It was presented at the PX4 Developer Conference 2023.</p>',20),s("lite-youtube",{videoid:"1c4TqEn3MZ0",title:"Debugging PX4 - Niklas Hauser, Auterion AG"},null,-1),i('<p><strong>Overview:</strong> The inspection tools built into PX4 via Mavlink Shell (NSH) as well as interpretation of the PX4 uLog after a flight require PX4 to still be functioning. However, the most problematic bugs often manifest themselves in a (partially) hanging or crashed system. Therefore, we present the open-source Embedded Debug Tools project, which manages and configures probe, debugging and analysis tools for PX4 and NuttX:</p><ul><li>Debug interfaces (SWD) and the associated debug probes (J-Link, STLink) and libraries (JLinkGDBServer, OpenOCD).</li><li>How to install and configure <code>arm-none-eabi-gdb(-py3)</code> for debugging your ELF.</li><li>Commonly used GDB commands and scripts.</li><li>Advanced GDB scripting via its Python API.</li><li>Inspection of NuttX RTOS component internals: tasks, semaphores, scheduler.</li><li>Inspecting peripheral state with CMSIS-SVD files and custom visualizations.</li><li>Coredumping for post-mortem debugging via CrashDebug.</li><li>Hardfault analysis in a live system and via the hardfault log.</li><li>Remote GDB scripting via the Machine Interface.</li><li>Automated HiL testing of PX4 via combined GDB and NSH scripting.</li><li>ITM profiling over SWO pin using Orbuculum.</li><li>Thread/IRQ/Workqueue/Heap visualization and latency analysis using perfetto.</li><li>High-bandwidth ETM tracing over TRACE pins: J-Trace and ORBtrace mini.</li><li>We conclude with an overview of interesting related project and an outlook on the future of PX4 debugging.</li></ul><h2 id="embedded-debug-tools" tabindex="-1">Embedded Debug Tools <a class="header-anchor" href="#embedded-debug-tools" aria-label="Permalink to &quot;Embedded Debug Tools&quot;">​</a></h2><p>The <a href="https://pypi.org/project/emdbg/" target="_blank" rel="noreferrer">Embedded Debug Tools</a> connect several software and hardware debugging tools together in a user friendly Python package to more easily enable advanced use cases for ARM Cortex-M microcontrollers and related devices.</p><p>The library orchestrates the launch and configuration of hardware debug and trace probes, debuggers, logic analyzers, and waveform generators and provides analysis tools, converters, and plugins to provide significant insight into the software and hardware state during or after execution.</p><p>The <code>emdbg</code> library contains <a href="https://github.com/Auterion/embedded-debug-tools/blob/main/src/emdbg/debug/gdb.md#user-commands" target="_blank" rel="noreferrer">many useful GDB plugins</a> that make debugging PX4 easier. It also provides tools for <a href="https://github.com/Auterion/embedded-debug-tools/tree/main/ext/orbetto" target="_blank" rel="noreferrer">profiling PX4 in real-time</a>.</p>',6)]))}const b=a(r,[["render",n]]);export{u as __pageData,b as default};
